d-template-columns:repeat(3,1fr);gap:18px}.card{padding:26px;border:1px solid #e6e6e6;border-radius:10px}.card span{color:var(--orange);font-size:13px;font-weight:bold}.card p{color:var(--muted);font-size:15px}.about{background:var(--paper);padding:36px;border-radius:14px}.about p{max-width:820px}.contact{background:var(--ink);color:white;padding:36px;border-radius:14px}.contact p{max-width:650px;color:#d5d8df}.widget h2{font-size:26px}.post{padding:25px 0;border-bottom:1px solid #eee}.post-title{font-size:25px}.post-body{overflow-wrap:anywhere}.post-body img{max-width:100%;height:auto}.post-body iframe{max-width:100%}.blog-pager{display:flex;justify-content:space-between;padding:25px 0}footer{color:var(--muted);font-size:13px;border-top:1px solid #eee}.status-msg-wrap{margin:10px 0}a:focus-visible{outline:3px solid #f4510b;outline-offset:5px}@media(max-width:760px){nav{align-items:flex-start;flex-direction:column}.menu{gap:16px}.hero{grid-template-columns:1fr;gap:25px;padding:42px 0}.visual{transform:none}.cards{grid-template-columns:1fr}section{padding:32px 0}.about,.contact{padding:24px}h1{letter-spacing:-1px}}
