ading{display:flex;justify-content:space-between;gap:60px;align-items:end;margin-bottom:36px}.section-heading h2{margin:16px 0 0}.section-heading p{max-width:310px;font-size:14px;color:var(--muted)}.cards{display:block}.card{position:relative;border:0;border-top:1px solid #d8dddf;border-radius:0;padding:28px 0;display:grid;grid-template-columns:130px 1.1fr 1fr;gap:25px;align-items:center;transition:padding .25s,background .25s}.card:last-child{border-bottom:1px solid #d8dddf}.card span{font-family:'Space Mono',monospace;font-size:10px;font-weight:400}.card h3{font-size:clamp(24px,3.2vw,42px);line-height:1.1;letter-spacing:-1.5px;margin:0;font-weight:800}.card p{font-size:13px;margin:0}.card:hover{padding-left:20px;padding-right:20px;background:#f5b93516;border-color:#d8dddf}.card:hover h3{color:var(--orange)}#keahlian{background:var(--gray)}.expertise{gap:90px}.expertise>p{font-size:20px;line-height:1.6;max-width:540px}.expertise h3{font-size:18px;letter-spacing:-.5px}.expertise div p{font-size:14px}.about{background:var(--blue);color:var(--paper);padding:50px;border-radius:24px;position:relative}.about .eyebrow{color:var(--yellow)}.about h2{font-size:clamp(32px,4vw,52px)}.about p{color:#e5eaf0;max-width:710px;font-size:14px}.about:after{content:'↗';position:absolute;right:30px;top:20px;color:var(--yellow);font-size:120px;opacity:.5}.empty-blog{background:var(--gray);border:0;border-radius:20px;padding:35px}.empty-blog h3{font-size:23px}.empty-blog p{color:var(--muted);font-size:14px}.topic{font-family:'Space Mono',monospace;font-size:10px;border-color:#cfd5d8;background:var(--paper)}#video{background:var(--gray)}.video-grid{gap:22px}.video-card{background:var(--paper);border:0;border-radius:18px;transition:transform .25s}.video-card:hover{transform:translateY(-7px)}.video-card a{padding:20px;font-family:'Space Mono',monospace;font-size:11px}.contact{background:var(--orange);border-radius:24px;padding:48px;color:var(--ink)}.contact .eyebrow{color:var(--ink)}.contact h2{font-size:clamp(40px,6vw,82px);letter-spacing:-3px}.contact h2 span{color:var(--paper)}.contact p{color:var(--ink);font-size:14px}.contact .widget-content{font-family:'Space Mono',monospace;font-size:11px;border-top:1px solid #17222d40;padding-top:20px}footer{color:#c1c8cd;max-width:1300px;padding:35px 40px;border:0;font-size:11px}.post{padding:30px 0}.post-title{font-size:30px;letter-spacing:-1px}.post-title a{text-decoration:none}.post-title a:hover{color:var(--orange)}@keyframes float-a{50%{transform:translateY(-12px) rotate(-8deg)}}@keyframes float-b{50%{transform:translateY(12px) rotate(8deg)}}@media(min-width:1500px){h1{font-size:155px}}@media(max-width:900px){nav{padding:25px}.hero{padding:20px 30px 30px;min-height:620px}h1{letter-spacing:-5px;font-size:11vw}.floating-card{width:125px}.float-one{left:0;top:5%}.float-two{right:0;bottom:-30px}.hero-title{margin-top:65px;margin-bottom:65px}.hero-kicker{font-size:10px}.strip{padding:35px 25px 10px;gap:10px}.strip strong{font-size:15px}.strip .pill{font-size:8px}section{padding:50px 30px}.card{grid-template-columns:90px 1fr 1fr;gap:15px}.card h3{font-size:28px}.section-heading{gap:25px}.expertise{gap:30px}}@media(max-width:600px){nav{gap:20px}.menu{gap:17px;width:100%;justify-content:space-between}.menu a{font-size:10px}.menu a:last-child{padding:5px 10px}.hero{padding:15px 22px 25px;min-height:650px}.hero-location{display:none}.hero-title{margin:70px 0 65px}.hero-kicker{letter-spacing:2px}h1{font-size:13vw;letter-spacing:-3px;margin:30px 0 65px}.floating-card{width:96px;border-radius:12px;padding:10px}.floating-card .data-label{font-size:6px}.floating-card strong{font-size:7px;margin-top:7px}.mini-table{gap:3px;margin-top:8px}.mini-table i{height:7px}.float-one{top:-55px;left:0}.float-two{bottom:-72px;right:0}.floating-card .bars{height:42px;gap:3px}.hero-bottom{display:block;margin-top:85px}.hero-bottom p{font-size:12px}.hero-bottom .button{margin-top:10px}.hero-foot{font-size:7px;gap:15px}.strip{grid-template-columns:1fr;padding:28px 22px 0;gap:10px;border-radius:26px 26px 0 0}.strip>div{display:grid;grid-template-columns:1fr 1.2fr;text-align:left;gap:10px;padding:20px}.strip .data-label{font-size:8px}.strip strong{font-size:15px}.strip .pill{grid-column:2;justify-self:start;font-size:7px}section{padding:45px 22px}h2{letter-spacing:-1.5px}.section-heading{display:block;margin-bottom:25px}.section-heading p{max-width:100%;margin-top:20px}.card{grid-template-columns:1fr;padding:24px 0;gap:12px}.card h3{font-size:32px}.card span{font-size:9px}.card p{max-width:360px}.card:hover{padding-left:10px;padding-right:10px}.expertise{display:block}.expertise>p{font-size:18px}.about{padding:28px;border-radius:18px}.about:after{display:none}.about h2{font-size:32px}.video-grid{grid-template-columns:1fr}.contact{padding:28px}.contact h2{font-size:44px;letter-spacing:-2px}.empty-blog{padding:24px}.empty-blog h3{font-size:20px}.preview-note{font-size:9px}footer{padding:30px 22px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}}

/* Continuous left-to-right motion for the three introduction cards. */
.strip{display:block;overflow:hidden;padding:46px 0 18px;position:relative}
.strip .marquee-track{display:flex;flex-direction:row;align-items:stretch;background:transparent;padding:0;border-radius:0;width:max-content;gap:0;animation:andat-cards-right 32s linear infinite;will-change:transform}
.strip .marquee-group{display:flex;flex:none;gap:20px;padding-right:20px}
.strip .marquee-card{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;flex:0 0 clamp(280px,29vw,370px);min-height:240px;padding:35px 22px;background:var(--gray);border-radius:7px}
.strip .marquee-card strong{font-size:clamp(19px,2vw,27px)}
.strip .marquee-card .data-label{font-size:12px}
.strip .marquee-card .pill{font-size:11px;padding:10px 20px}
.strip .marquee-toolbar{display:flex;flex-direction:row;align-items:center;background:transparent;border-radius:0;gap:0;justify-content:flex-end;padding:18px 30px 0}
.marquee-toggle{font:10px 'Space Mono',monospace;border:1px solid #ccd1d4;border-radius:25px;background:transparent;color:var(--ink);padding:8px 14px;cursor:pointer}
.marquee-toggle:focus-visible{outline:3px solid var(--orange);outline-offset:3px}
.marquee-toggle .resume-label{display:none}.is-paused .marquee-toggle .pause-label{display:none}.is-paused .marquee-toggle .resume-label{display:inline}
.strip:hover .marquee-track,.strip:focus-within .marquee-track,.strip.is-paused .marquee-track{animation-play-state:paused}
@keyframes andat-cards-right{from{transform:translateX(-50%)}to{transform:translateX(0)}}
@media(max-width:600px){.strip{padding:28px 0 10px}.strip .marquee-card{flex-basis:280px;min-height:210px}.strip .marquee-card .data-label{font-size:10px}.strip .marquee-card strong{font-size:22px}.strip .marquee-card .pill{font-size:10px}.marquee-toolbar{padding-right:22px}}
@media(prefers-reduced-motion:reduce){.strip .marquee-track{animation:none;transform:none;width:100%;will-change:auto}.strip .marquee-group{width:100%;flex-wrap:wrap;justify-content:center;padding:0 22px}.strip .marquee-group[aria-hidden='true']{display:none}.strip .marquee-card{flex:1 1 260px}.marquee-toolbar{display:none}}

#visi-misi{padding-top:15px}.purpose-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:35px}.purpose-card{border-radius:22px;padding:38px}.purpose-card.vision{background:var(--ink);color:var(--paper)}.purpose-card.mission{background:var(--yellow);color:var(--ink)}.purpose-card h3{font-size:42px;letter-spacing:-1.8px;line-height:1.1;margin:20px 0}.purpose-card .data-label{font-size:10px}.purpose-card.vision .data-label{color:var(--yellow)}.purpose-card p{font-size:21px;line-height:1.6;margin:0}.purpose-card ul{padding-left:19px;margin:0;font-size:15px;line-height:1.8}.purpose-card li+li{margin-top:18px}.purpose-card .widget{margin:0}#pendekatan{background:var(--gray)}#pendekatan h2{max-width:980px}.principle-intro{display:flex;gap:45px;align-items:center;justify-content:space-between;margin:25px 0 40px}.principle-intro p{max-width:730px;color:var(--muted);font-size:16px;line-height:1.8}.principle-link{font:11px 'Space Mono',monospace;color:var(--ink);text-underline-offset:5px;flex-shrink:0}.principle-link:hover{color:var(--orange)}.principle-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.principle-grid article{border-top:2px solid var(--blue);padding-top:22px}.principle-grid .data-label{color:var(--blue);font-size:10px}.principle-grid h3{font-size:22px;letter-spacing:-.7px;line-height:1.3}.principle-grid p{font-size:14px;color:var(--muted)}.integrity-note{background:var(--paper);border-left:4px solid var(--orange);border-radius:0 18px 18px 0;margin-top:35px;padding:28px 32px}.integrity-note .data-label{color:var(--orange);font-size:10px}.integrity-note h3{font-size:26px;letter-spacing:-1px;margin:12px 0}.integrity-note p{font-size:15px;max-width:820px;margin-bottom:0;color:var(--muted)}@media(max-width:760px){.purpose-grid{grid-template-columns:1fr}.purpose-card{padding:28px}.purpose-card p{font-size:19px}.purpose-card h3{font-size:34px}.principle-intro{display:block;margin-bottom:30px}.principle-grid{grid-template-columns:1fr;gap:20px}.principle-grid h3{margin:15px 0}.integrity-note{padding:24px}.integrity-note h3{font-size:23px}}

.services-heading{margin-bottom:35px}.services-heading h2{margin:18px 0}.services-heading>p{font-size:16px;max-width:530px;color:var(--muted);line-height:1.6}.service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.service-card{padding:30px 34px;border-radius:18px;min-height:250px;transition:transform .25s;display:flex;flex-direction:column;justify-content:flex-start}.service-card:hover{transform:translateY(-5px)}.service-orange{background:var(--orange);color:white}.service-navy{background:var(--ink);color:white}.service-blue{background:var(--blue);color:white}.service-gray{background:var(--gray);color:var(--ink)}.service-yellow{background:var(--yellow);color:var(--ink)}.service-top{display:flex;gap:25px;align-items:center;margin-bottom:20px}.service-top svg{width:43px;height:43px;flex-shrink:0}.service-number{display:flex;align-items:center;gap:13px;font:700 12px 'Space Mono',monospace}.service-number i{display:block;height:1px;width:32px;background:currentColor;opacity:.4}.service-card h3{font:800 23px/1.2 Montserrat,sans-serif;letter-spacing:-.7px;margin:0 0 13px}.service-card p{font-size:15px;line-height:1.5;margin:0;max-width:420px}.service-card .widget{margin:0}.service-gray p{color:var(--blue)}.service-wide{grid-column:1/-1;min-height:210px;align-items:center;text-align:center}.service-wide .service-top{justify-content:center}.service-wide p{max-width:610px}.contact-actions{display:flex;flex-wrap:wrap;align-items:center;gap:20px;margin-top:12px}.contact .whatsapp-button{background:var(--ink);color:white}.contact .whatsapp-button:hover{background:var(--paper);color:var(--ink)}.contact-number{font:12px 'Space Mono',monospace;color:var(--ink);text-underline-offset:4px}.menu .nav-whatsapp{border-color:var(--orange);color:var(--orange)}.hero-whatsapp{display:inline-block;color:var(--paper);text-underline-offset:5px;font-size:12px;margin-left:16px}.hero-whatsapp:hover{color:var(--yellow)}@media(max-width:760px){.service-card{padding:25px;min-height:240px}.service-card h3{font-size:20px}.service-card p{font-size:14px}.service-top{gap:15px}}@media(max-width:480px){.service-grid{gap:12px}.service-card{padding:18px 14px;min-height:250px;border-radius:12px}.service-card h3{font-size:16px;letter-spacing:-.4px}.service-card p{font-size:12px;line-height:1.45}.service-top{gap:10px;margin-bottom:18px}.service-top svg{width:31px;height:31px}.service-number{font-size:10px;gap:8px}.service-number i{width:18px}.service-wide{min-height:190px}.services-heading>p{font-size:14px}.hero-whatsapp{display:block;margin:18px 0 0}.contact-actions{align-items:flex-start;flex-direction:column}}

/* Make the contact action prominent and shorten service cards. */
#kontak .contact{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(330px,1fr);align-items:center;gap:42px;padding:42px}
#kontak .contact h2{font-size:clamp(30px,3.8vw,50px);line-height:1.13;letter-spacing:-1.7px;margin:20px 0}
#kontak .contact-copy>p:not(.eyebrow){font-size:14px;line-height:1.7;max-width:480px;margin:0 0 18px}
.contact-value{font:10px/1.7 'Space Mono',monospace;color:var(--ink)}
#kontak .contact .widget-content{border:0;padding:0;font-family:Inter,sans-serif}
#kontak .contact-panel{background:var(--paper);border-radius:18px;padding:30px;box-shadow:0 12px 30px #17222d18;color:var(--ink)}
.contact-panel>.data-label{color:var(--blue);font-size:10px}
.contact-panel h3{font-size:24px;letter-spacing:-.8px;margin:14px 0 12px}
#kontak .contact-panel p{font-size:13px;line-height:1.6;margin:0 0 22px}
#kontak .whatsapp-button{display:flex;align-items:center;justify-content:center;gap:12px;width:100%;padding:17px 18px;border-radius:12px;background:var(--ink);color:white;font:700 14px/1.4 Inter,sans-serif;box-shadow:0 6px 0 #17222d18;transition:transform .2s,box-shadow .2s,background .2s}
#kontak .whatsapp-button svg{width:25px;height:25px;flex-shrink:0}
#kontak .whatsapp-button span{font:inherit;margin:0}
#kontak .whatsapp-button .cta-arrow{font-size:20px;margin-left:auto}
#kontak .whatsapp-button:hover{background:var(--blue);color:white;transform:translateY(-3px);box-shadow:0 9px 0 #17222d18}
#kontak .whatsapp-button:active{transform:translateY(0)}
#kontak .contact-number{display:block;text-align:center;font:500 14px 'Space Mono',monospace;margin-top:20px;text-underline-offset:4px}
.contact-help{display:block;font:11px/1.6 Inter,sans-serif;text-align:center;color:var(--muted);margin-top:10px}
.service-grid{gap:16px}.service-card{padding:23px 26px;min-height:0}.service-top{margin-bottom:13px;gap:18px}.service-top svg{width:33px;height:33px}.service-card h3{font-size:21px;margin-bottom:9px}.service-card p{font-size:14px;line-height:1.5;max-width:480px}.service-wide{min-height:0;padding:24px 30px}.service-wide p{max-width:660px}.services-heading{margin-bottom:26px}
@media(max-width:900px){#kontak .contact{grid-template-columns:1fr;gap:28px;padding:30px}#kontak .contact h2{font-size:40px}.contact-panel{max-width:600px}.service-card{padding:21px}}
@media(max-width:480px){#kontak .contact{padding:23px;gap:24px}#kontak .contact h2{font-size:32px;letter-spacing:-1px}#kontak .contact-panel{padding:22px 18px}.contact-panel h3{font-size:22px}#kontak .whatsapp-button{font-size:13px;padding:15px 12px;gap:9px}#kontak .contact-number{font-size:12px}.service-grid{gap:12px}.service-card{padding:17px 14px;min-height:0}.service-card h3{font-size:16px}.service-card p{font-size:12px}.service-top{margin-bottom:12px;gap:10px}.service-top svg{width:28px;height:28px}.service-wide{padding:20px}}
@media(prefers-reduced-motion:reduce){#kontak .whatsapp-button{transition:none}#kontak .whatsapp-button:hover{transform:none}}
.brand.brand-logo{display:inline-flex;align-items:center;justify-content:center;background:#fff;padding:8px 14px;border-radius:10px;line-height:0;flex-shrink:0}.brand-logo img{display:block;width:152px;height:auto;max-width:100%}@media(max-width:600px){.brand.brand-logo{padding:7px 12px}.brand-logo img{width:132px}}
/* Consolidated company and expertise sections. */
#tentang.company-section{padding-top:48px;padding-bottom:48px}
.company-heading{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.company-heading h2{font-size:clamp(30px,3.7vw,48px);margin:16px 0 0;letter-spacing:-1.7px}
.company-summary{padding-top:8px}.company-summary p{font-size:14px;line-height:1.75;color:var(--muted);margin:0 0 12px}
.company-section #visi-misi{padding:0;margin-top:26px;gap:18px}
.company-section .purpose-card{padding:26px 30px;border-radius:16px}
.company-section .purpose-card h3{font-size:28px;letter-spacing:-1px;margin:13px 0}
.company-section .purpose-card p{font-size:17px;line-height:1.6}
.company-section .purpose-card ul{font-size:14px;line-height:1.65}
.company-section .purpose-card li+li{margin-top:10px}
#keahlian.combined-expertise{padding-top:45px;padding-bottom:45px;background:var(--gray)}
.combined-expertise h2{font-size:clamp(30px,3.7vw,48px);letter-spacing:-1.7px;margin:16px 0 22px}
.combined-expertise .principle-intro{gap:30px;margin:0 0 26px}
.combined-expertise .principle-intro p{font-size:14px;line-height:1.7;max-width:780px;margin:0}
.combined-expertise .principle-grid{gap:22px}
.combined-expertise .principle-grid article{padding-top:17px}
.combined-expertise .principle-grid h3{font-size:20px;margin:14px 0 10px}
.combined-expertise .principle-grid p{font-size:13px;line-height:1.65;margin:0}
.combined-expertise .integrity-note{margin-top:25px;padding:22px 26px;border-radius:0 14px 14px 0}
.combined-expertise .integrity-note h3{font-size:23px;margin:10px 0}
.combined-expertise .integrity-note p{font-size:14px;line-height:1.65;margin:0;max-width:100%}
#pendekatan{scroll-margin-top:30px}
@media(max-width:760px){#tentang.company-section,#keahlian.combined-expertise{padding:34px 22px}.company-heading{grid-template-columns:1fr;gap:18px}.company-summary{padding:0}.company-summary p:last-child{margin-bottom:0}.company-section #visi-misi{grid-template-columns:1fr;margin-top:22px;gap:14px}.company-section .purpose-card{padding:23px}.company-section .purpose-card p{font-size:16px}.company-section .purpose-card h3{font-size:26px}.combined-expertise .principle-intro p{margin-bottom:16px}.combined-expertise .principle-grid{gap:20px}.combined-expertise .integrity-note{padding:22px}.combined-expertise .integrity-note h3{font-size:21px}}

/* Content stays visible even when Blogger omits uninitialized widgets. */
.editable-shell>.widget-fallback{display:block}
.editable-shell>.editable-widget:empty{display:none}
.editable-shell:has(>.editable-widget .widget-content:not(:empty))>.widget-fallback{display:none}
.editable-widget .section,.editable-widget .widget{margin:0;padding:0}
.post-summary{max-height:140px;overflow:hidden;position:relative;margin-bottom:16px}.post-summary img,.post-summary iframe,.post-summary video{display:none}.post-summary:after{content:'';position:absolute;bottom:0;left:0;right:0;height:25px;background:linear-gradient(transparent,var(--paper));pointer-events:none}.post-body{font-size:16px;line-height:1.85;max-width:850px}.post-body pre{overflow:auto}.post-body table{max-width:100%;display:block;overflow:auto}.article-heading{font:800 clamp(30px,4.5vw,52px)/1.2 Montserrat,sans-serif;color:var(--ink);letter-spacing:-1.5px;margin:0 0 26px;text-align:left}.post .post-body h1{font-size:30px;line-height:1.3;color:var(--ink);letter-spacing:-1px;margin:25px 0}.post-summary h1{font-size:23px;line-height:1.3;color:var(--ink);letter-spacing:-.5px;margin:10px 0}.article-more,.back-to-blog{display:inline-block;color:var(--orange);font-weight:700;margin-top:18px}.andat-no-posts{padding:24px;background:var(--gray);border-radius:12px}.feed-excerpt{font-size:15px;line-height:1.8;color:var(--muted);max-width:830px}.feed-status{padding:20px;border-radius:12px;background:var(--gray);font-size:14px}.feed-pager{display:flex;justify-content:space-between;gap:15px;margin-top:25px}.feed-pager button,.feed-retry{font:600 13px Inter,sans-serif;padding:12px 18px;border:1px solid var(--ink);border-radius:24px;background:var(--paper);color:var(--ink);cursor:pointer}.feed-pager button:hover,.feed-retry:hover{background:var(--ink);color:white}#andat-feed-fallback[aria-busy='true']{opacity:.7}/* Navbar tetap terlihat saat halaman digulir */
header {
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 3px 16px #17222d25;
}

header nav {
  padding-top: 12px;
  padding-bottom: 12px;
}

html {
  scroll-padding-top: 140px;
}

/* Daftar artikel menjadi kartu yang bisa digeser */
#andat-feed-fallback:not(:has(.post-body)) {
  display: flex;
  gap: 22px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding: 4px 2px 18px;
  scrollbar-width: thin;
  scrollbar-color: #FF5800 #F0F2F2;
}

#andat-feed-fallback:not(:has(.post-body)) > .post {
  flex: 0 0 calc((100% - 44px) / 3);
  min-width: 0;
  min-height: 260px;
  padding: 24px;
  border: 1px solid #dce1e4;
  border-top: 5px solid #2A5680;
  border-radius: 16px;
  background: #FAFAF8;
  scroll-snap-align: start;
  display: flex;
  flex-direction: column;
}

#andat-feed-fallback:not(:has(.post-body)) .post-title {
  font-size: 19px;
  line-height: 1.4;
  letter-spacing: -.5px;
  margin: 0 0 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

#andat-feed-fallback:not(:has(.post-body)) .feed-excerpt {
  font-size: 13px;
  line-height: 1.7;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

#andat-feed-fallback:not(:has(.post-body)) .article-more {
  margin-top: auto;
  padding-top: 18px;
  font-size: 12px;
}

@media (max-width: 900px) {
  #andat-feed-fallback:not(:has(.post-body)) > .post {
    flex-basis: calc((100% - 22px) / 2);
  }
}

@media (max-width: 600px) {
  #andat-feed-fallback:not(:has(.post-body)) > .post {
    flex-basis: 85%;
  }
}

body.script:
//
(function () {
  'use strict';
  var root = document.getElementById('andat-feed-fallback');
  if (!root) return;
  var nativePosts = document.querySelector('#artikel .andat-posts .post, #artikel #Blog1 .post');
  if (nativePosts) { root.remove(); return; }
  var home = new URL(root.dataset.blogHome || '/', location.href);
  var path = location.pathname;
  var single = /^\/\d{4}\/\d{2}\//.test(path) || /^\/p\//.test(path);
  var start = 1;
  var pageSize = 6;
  function node(tag, text, cls) {
    var el = document.createElement(tag);
    if (text !== undefined) el.textContent = text;
    if (cls) el.className = cls;
    return el;
  }
  function postUrl(entry) {
    var link = (entry.link || []).find(function (x) { return x.rel === 'alternate'; });
    if (!link) return home.href;
    var url = new URL(link.href, home);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : home.href;
  }
  function bodyFragment(entry) {
    var parsed = new DOMParser().parseFromString((entry.content || entry.summary || {}).$t || '', 'text/html');
    parsed.querySelectorAll('script,object,embed,base,meta,link').forEach(function (el) { el.remove(); });
    parsed.body.querySelectorAll('*').forEach(function (el) {
      Array.from(el.attributes).forEach(function (attr) {
        if (/^on/i.test(attr.name) || (/^(href|src|action)$/i.test(attr.name) && /^\s*javascript:/i.test(attr.value))) el.removeAttribute(attr.name);
      });
    });
    return parsed.body;
  }
  function renderPost(entry) {
    var article = node('article', undefined, 'post');
    var title = (entry.title || {}).$t || 'Artikel ANDAT';
    var heading = node(single ? 'h1' : 'h2', undefined, single ? 'article-heading' : 'post-title');
    if (single) heading.textContent = title;
    else { var link = node('a', title); link.href = postUrl(entry); heading.appendChild(link); }
    article.appendChild(heading);
    var body = bodyFragment(entry);
    if (single) {
      var content = node('div', undefined, 'post-body');
      while (body.firstChild) content.appendChild(body.firstChild);
      article.appendChild(content);
    } else {
      var summary = (body.textContent || '').replace(/\s+/g, ' ').trim();
      article.appendChild(node('p', summary.slice(0, 240) + (summary.length > 240 ? '…' : ''), 'feed-excerpt'));
    }
    var more = node('a', single ? '← Kembali ke Blog ANDAT' : 'Baca selengkapnya ↗', 'article-more');
    more.href = single ? home.href + '#artikel' : postUrl(entry);
    article.appendChild(more);
    return article;
  }
  async function load(scroll) {
    root.replaceChildren(node('p', 'Memuat artikel ANDAT…', 'feed-status'));
    root.setAttribute('aria-busy', 'true');
    try {
      var url = new URL('feeds/posts/default', home);
      url.searchParams.set('alt', 'json');
      url.searchParams.set('max-results', single ? '1' : String(pageSize + 1));
      if (single) url.searchParams.set('path', path);
      else url.searchParams.set('start-index', String(start));
      var response = await fetch(url.href, { credentials: 'omit' });
      if (!response.ok) throw new Error('Feed unavailable');
      var data = await response.json();
      var entries = data.entry ? [data.entry] : ((data.feed || {}).entry || []);
      root.replaceChildren();
      if (!entries.length) root.appendChild(node('p', single ? 'Artikel belum tersedia di feed publik. Pastikan postingan sudah dipublikasikan.' : 'Belum ada artikel untuk ditampilkan.', 'feed-status'));
      entries.slice(0, single ? 1 : pageSize).forEach(function (entry) { root.appendChild(renderPost(entry)); });
      if (!single && (start > 1 || entries.length > pageSize)) {
        var pager = node('div', undefined, 'feed-pager');
        if (start > 1) {
          var prev = node('button', '← Lebih baru'); prev.type = 'button';
          prev.onclick = function () { start = Math.max(1, start - pageSize); load(true); }; pager.appendChild(prev);
        }
        if (entries.length > pageSize) {
          var next = node('button', 'Lebih lama →'); next.type = 'button';
          next.onclick = function () { start += pageSize; load(true); }; pager.appendChild(next);
        }
        root.appendChild(pager);
      }
      if (scroll) root.scrollIntoView({ block: 'start' });
    } catch (err) {
      root.replaceChildren(node('p', 'Artikel belum dapat dimuat. Silakan coba lagi.', 'feed-status'));
      var retry = node('button', 'Muat ulang artikel', 'feed-retry');retry.type = 'button';retry.onclick = function () { load(false); };root.appendChild(retry);
    } finally { root.setAttribute('aria-busy', 'false'); }
  }
  load(false);
}());

//
